    pers_btn_restart: "Rozpocznij test ponownie",
    pers_questions: [
      { q: "1. Kiedy czujesz, że Twoje baterie życiowe są całkowicie wyczerpane, najchętniej:", a: "Spędzam czas wśród ludzi, rozmawiam z przyjaciółmi lub kimś bliskim, by wymienić się energią.", b: "Zaszywam się w ciszy, czytam, rozmyślam lub odpoczywam w samotności, by wrócić do siebie." },
      { q: "2. Na dużych spotkaniach towarzyskich lub wydarzeniach zazwyczaj:", a: "Chętnie rozmawiam z wieloma osobami, również nowo poznanymi, i czuję, że to mnie nakręca.", b: "Trzymam się boku, rozmawiam dłużej z kilkoma dobrze znanymi mi ludźmi i szybko odczuwam zmęczenie hałasem." },
      { q: "3. Kiedy w Twoim życiu dzieje się coś ważnego lub przeżywasz silne emocje:", a: "Mam naturalną potrzebę natychmiastowego przegadania tego z kimś, by poukładać to sobie w głowie.", b: "Najpierw muszę to samodzielnie przetrawić w swoim wnętrzu i dopiero po czasie opowiadam o tym innym." },
      { q: "4. W działaniu i pracy najchętniej wybierasz:", a: "Pracę zespołową, burzę mózgów i stały kontakt z ludźmi – w grupie rodzą się moje najlepsze pomysły.", b: "Samodzielne, skupione działanie w spokojnym miejscu, gdzie nikt mi nie przerywa." },
      { q: "5. Ludzie z Twojego otoczenia najczęściej opisują Cie jako osobę:", a: "Otwartą, komunikatywną, pełną ekspresji i łatwą w obejściu.", b: "Spokojną, powściągliwą, refleksyjną i trudniejszą do bliższego poznania." },
      { q: "6. Co jest dla Ciebie większym wyzwaniem w codzienności?", a: "Przymusowe, długie przebywanie w izolacji i samotności.", b: "Brak przestrzeni dla siebie i nieustanne przebywanie w głośnym tłumie." },
      { q: "7. Kiedy zaczynasz nowy projekt lub uczysz się czegoś nowego, najbardziej interesuje Cię:", a: "Praktyczne zastosowanie, sprawdzone procedury i jasne, namacalne przykłady.", b: "Ogólna idea, ukryte powiązania, teorie i to, jak ten temat rozwija wyobraźnię." },
      { q: "8. Kiedy opowiadasz komuś o jakimś wydarzeniu ze swojego życia:", a: "Skupiasz się na szczegółach, faktach, chronologii i tym, co realnie się wydarzyło.", b: "Przeskakujesz między wątkami, skupiasz się na atmosferze, metaforach i płynących z tego wnioskach." },
      { q: "9. W codziennym życiu najbardziej ufasz:", a: "Swojemu dotychczasowemu, sprawdzonemu doświadczeniu i temu, co podpowiadają logiczne fakty.", b: "Swojej intuicji, wewnętrznemu głosowi i przeczuciom, nawet jeśli nie mam na to jeszcze dowodów." },
      { q: "10. Kiedy myślisz o przyszłości i swoich ukrytych talentach, Twój umysł:", a: "Trzyma się ziemi – analizuje obecną sytuację i realne, najbliższe kroki.", b: "Snuje wielkie wizje, marzenia i dostrzega nieskończone możliwości, które dopiero mogą się wydarzyć." },
      { q: "11. Jaki typ literatury, bajek czy opowieści pociąga Cię najbardziej?", a: "Realistyczne historie, biografie lub literatura faktu, z których mogę wyciągnąć konkretne lekcje.", b: "Opowieści z głęboką symboliką, światy pełne magii lub metaforyczne bajki dotykające tajemnic duszy." },
      { q: "12. Jeśli ktoś opisuje Ci jakiś problem, Twoją pierwszą reakcją jest:", a: "Zauważenie konkretnych szczegółów i szukanie doraźnego, namacalnego rozwiązania tu i teraz.", b: "Spojrzenie na szerszy kontekst, szukanie ukrytej przyczyny emocjonalnej i duchowej esencji problemu." },
      { q: "13. Kiedy stajesz przed trudnym, życiowym wyborem, starasz się przede wszystkim:", a: "Odciąć emocje, zrobić chłodną listę zysków i strat oraz wybrać najbardziej racjonalną opcję.", b: "Zapytać siebie, co czuję, jak ta decyzja wpłynie na moich bliskich i czy zachowam wewnętrzną harmonię." },
      { q: "14. Kiedy widzisz, że ktoś w Twoim otoczeniu popełnia wyraźny błąd:", a: "Mówię o tym bezpośrednio i konstruktywnie – prawda i skuteczność są dla mnie najważniejsze.", b: "Staram się dobrać słowa niezwykle delikatnie, by nie zranić niczyich uczuć i nie wywołać konfliktu." },
      { q: "15. W relacjach międzyludzkich i pracy najbardziej cenisz u innych:", a: "Spójność logiczną, obiektywizm, sprawiedliwość i trzymanie się zasad.", b: "Empatię, wrażliwość, gotowość do niesienia pomocy i ciepłą atmosferę." },
      { q: "16. Gdy wchodzisz w dyskusję lub spór, Twoim głównym celem jest:", a: "Udowodnienie racji za pomocą twardych, logicznych argumentów i dojście do prawdy.", b: "Zrozumienie punktu widzenia drugiej strony i znalezienie kompromisu, by oczyścić atmosferę." },
      { q: "17. Co sprawia Ci większą trudność w codziennych relacjach?", a: "Wyrażanie i okazywanie głębokich wzruszeń oraz mówienie o swoich subtelnych emocjach.", b: "Odmawianie innym, stawianie twardych granic i radzenie sobie z cudzą krytyką." },
      { q: "18. Kiedy oglądasz film lub słuchasz opowieści, najbardziej porusza Cię:", a: "Genialnie skonstruowana, błyskotliwa i logiczna intryga, która zmusza do myślenia.", b: "Głęboki portret psychologiczny bohaterów, ich relacje, wzajemne wsparcie i ukryte uczucia." },
      { q: "19. Twój idealny dzień lub proces twórczy charakteryzuje się tym, że:", a: "Mam jasny plan działania, listę zadań i poczucie, że kontroluję czas.", b: "Działam pod wpływem impulsu, płynę z energią dnia i pozwalam sobie na pełną swobodę." },
      { q: "20. Kiedy planujesz wyjazd, wakacje lub ważne przedsięwzięcie:", a: "Wolę mieć wszystko wcześniej zarezerwowane, zaplanowane i dopięte na ostatni guzik, by uniknąć stresu.", b: "Rezerwuję tylko to, co niezbędne, a resztę zostawiam losowi – uwielbiam improwizować na miejscu." },
      { q: "21. Jak reagujesz, gdy niespodziewane okoliczności całkowicie burzą Twoje wcześniejsze ustalenia?", a: "Czuję irytację i napięcie w ciele – nie lubię, gdy coś wytrąca mnie z równego rytmu.", b: "Podchodzę do tego z ciekawością i lekkością – traktuję to jako nową, ekscytującą możliwość." },
      { q: "22. Spójrz na przestrzeń wokół siebie (biurko, pokój). Co tam widzisz?", a: "Porządek, posegregowane rzeczy, gdzie każdy przedmiot ma swoje jasne, stałe miejsce.", b: "Artystyczny nieład, rzeczy odłożone pod wpływem chwili – w tym chaosie mam swój własny system." },
      { q: "23. Kiedy masz do wykonania ważne zadanie lub projekt:", a: "Wolę zacząć od razu, rozłożyć pracę na równe etapy i skończyć przed czasem, by mieć spokój.", b: "Najlepiej działa na mnie lekka presja czasu – zbieram inspiracje, a finałowy krok robię zrywem w ostatniej chwili." },
      { q: "24. Poczucie bezpieczeństwa daje Ci sytuacja, w której:", a: "Wszystko jest jasne, stabilne, przewidywalne i ustrukturyzowane.", b: "Moje opcje pozostają otwarte, mam pełną wolność wyboru i nic mnie sztywno nie ogranicza." }
    ],

